#!/bin/bash
set -euo pipefail
umask 077
[[ $EUID -eq 0 ]] || { echo '请用 sudo bash 执行'; exit 1; }
test -f /opt/football-github-sync/sync.py
test -f /opt/football/models/active.json
exec 9>/run/football-quality-install.lock
flock -n 9 || exit 1
backup=/var/backups/football-quality-$(date +%Y%m%d-%H%M%S)
mkdir -p "$backup"
cp -a /opt/football-github-sync/sync.py "$backup/sync.py"
systemctl stop football-github-sync.timer football-github-sync.service
restore() {
 cp -a "$backup/sync.py" /opt/football-github-sync/sync.py
 systemctl start football-github-sync.timer || true
 echo "更新失败，已恢复同步脚本，备份：$backup"
}
trap restore ERR
install -d -m 755 /opt/football-audit
python3 - <<'FILES'
import base64,os,py_compile
from pathlib import Path
for name,encoded in {'/opt/football-audit/audit.py': '', '/opt/football-github-sync/sync.py': ''}.items():
 p=Path(name);tmp=p.with_suffix('.new');tmp.write_bytes(base64.b64decode(encoded));py_compile.compile(str(tmp),doraise=True);tmp.chmod(0o644 if 'football-audit/' in name else 0o600);os.replace(tmp,p)
FILES
cat > /etc/systemd/system/football-quality-audit.service <<'UNIT'
[Unit]
Description=Football quality diagnostics and prospective paper review
[Service]
Type=oneshot
User=football
Group=football
ExecStart=/opt/football/.venv/bin/python /opt/football-audit/audit.py
TimeoutStartSec=180
MemoryMax=384M
NoNewPrivileges=true
ProtectSystem=strict
ProtectHome=true
ReadWritePaths=/opt/football/reports
UMask=0077
UNIT
cat > /etc/systemd/system/football-quality-audit.timer <<'UNIT'
[Unit]
Description=Check football quality every ten minutes
[Timer]
OnBootSec=2min
OnUnitActiveSec=10min
[Install]
WantedBy=timers.target
UNIT
systemctl daemon-reload
systemctl start football-quality-audit.service
systemctl enable --now football-quality-audit.timer
systemctl start football-github-sync.timer
trap - ERR
systemctl start --no-block football-github-sync.service
echo 'QUALITY_UPDATE_OK：诊断报告已生成、模拟留档已启动、同步已提交。'
echo '不会自动更改比赛映射、训练模型或下注。未结算时复盘指标为空。'
echo '查看：journalctl -u football-quality-audit.service -u football-github-sync.service -n 20 --no-pager'
